import type { BetterFetchPlugin } from "@better-fetch/fetch";
import type { TokenStore } from "./browser-storage";

/**
 * Attaches the app's managed-auth bearer session to every Better Auth request (the app session is
 * bearer-only — no cookie), and drops it on sign-out so it can't be reused.
 */
export const bearerFetchPlugin = (store: TokenStore): BetterFetchPlugin => ({
  id: "runable-managed-auth-bearer",
  name: "Runable Managed Auth Bearer",
  hooks: {
    onRequest(context) {
      const token = store.getToken();
      if (!token) return context;
      const headers = new Headers(context.headers);
      if (!headers.has("authorization")) headers.set("authorization", `Bearer ${token}`);
      return { ...context, headers };
    },
    onSuccess(context) {
      if (new URL(context.request.url).pathname.endsWith("/sign-out")) store.clearToken();
    },
  },
});
